from pathlib import Path
p=Path('src/components/GeneratedOutfits.tsx');s=p.read_text(encoding='utf-8');s="import {outfitSteps,outfitStepIndex,runReviewBatch} from '../core/reviewTools';\n"+s
s=s.replace('onRename,disabled}', 'onRename,selected,onSelect,disabled}',1).replace("onRename:()=>Promise<void>;onEdit?", "onRename:()=>Promise<void>;selected:boolean;onSelect:()=>void;onEdit?",1)
s=s.replace("[title,setTitle]=useState(design.name);", "[title,setTitle]=useState(design.name),[notes,setNotes]=useState(design.reviewNotes??''),[needsEdits,setNeedsEdits]=useState(design.needsEdits??false),[noteStatus,setNoteStatus]=useState('');",1)
s=s.replace('<article className="generated-design-card"><WardrobeThumbnail','<article className="generated-design-card"><label className="review-select"><input type="checkbox" checked={selected} disabled={disabled} onChange={onSelect}/> Select {design.name}</label><WardrobeThumbnail',1)
s=s.replace('<h4>{title}</h4>', '''<h4>{title}</h4>{design.needsEdits&&<span className="review-needs-edits">Needs edits</span>}<details><summary>Review notes</summary><label><input type="checkbox" checked={needsEdits} disabled={disabled} onChange={e=>setNeedsEdits(e.target.checked)}/> Needs edits</label><textarea aria-label={'Notes for '+design.name} maxLength={2000} rows={3} value={notes} disabled={disabled} onChange={e=>{setNotes(e.target.value);setNoteStatus('Unsaved notes');}} placeholder="Collar, sleeve or fitting adjustments…"/><button className="btn" disabled={disabled} onClick={async()=>{try{await invoke('generated_outfits_annotate',{id:design.id,notes,needsEdits});await onRename();setNoteStatus('Notes saved');}catch(e){setError(String(e));}}}>Save notes</button><p role="status" className="hint-soft">{noteStatus}</p></details>''',1)
s=s.replace("const [query,setQuery]=useState(''),[sort,setSort]=useState('newest');", "const [query,setQuery]=useState(''),[sort,setSort]=useState('newest'),[reviewFilter,setReviewFilter]=useState('all'),[selected,setSelected]=useState<string[]>([]),[confirmBatch,setConfirmBatch]=useState<'approve'|'dismiss'>(),[progressStage,setProgressStage]=useState(''),[failedStage,setFailedStage]=useState('');\n const lastStage=useRef('');\n function trackStage(stage:string){lastStage.current=stage;setProgressStage(stage);}",1)
s=s.replace("setError('');let title=name.trim()", "setError('');setFailedStage('');trackStage('idea');let title=name.trim()",1)
s=s.replace("const owned=imageSession", "trackStage('loading');const owned=imageSession",1)
s=s.replace("   if(p.stage==='error'", "   if(p.stage!=='error'&&p.stage!=='stopped')trackStage(p.stage);\n   if(p.stage==='error'",1)
s=s.replace("}catch(e){await session.current?.stop()", "}catch(e){setFailedStage(lastStage.current);await session.current?.stop()",1)
a=s.index(' if(background)return')
s=s[:a]+''' async function batch(action:'approve'|'dismiss'){
  if(acting||running||!selected.length)return;setActing('batch');setConfirmBatch(undefined);setError('');
  const result=await runReviewBatch(selected,async id=>{if(action==='approve'){const saved=await invoke<GeneratedDesign>('generated_outfits_approve',{id});if(saved.outfitId)onSaved(saved.outfitId,saved.name);}else await invoke('generated_outfits_dismiss',{id});});
  setSelected(result.failed.map(f=>f.id));setStatus(result.succeeded.length+' designs '+(action==='approve'?'saved to Wardrobe.':'dismissed.'));
  if(result.failed.length)setError(result.failed.map(f=>(designs.find(d=>d.id===f.id)?.name??f.id)+': '+f.error).join(' / '));
  try{await reload();}catch(e){setError(String(e));}finally{setActing('');}
 }
 const visible=designs.filter(d=>(d.name+' '+d.prompt+' '+(d.reviewNotes??'')).toLowerCase().includes(query.toLowerCase())&&(reviewFilter==='all'||(reviewFilter==='needs'?d.needsEdits:!d.needsEdits))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='oldest'?a.createdAt-b.createdAt:b.createdAt-a.createdAt);
'''+s[a:]
s=s.replace('{error&&<p role="alert" className="msg-error">{error}</p>}', '''{(running||failedStage)&&<section className="outfit-progress" aria-label="Outfit creation steps"><p>{failedStage?'Stopped during: '+(outfitSteps.find(s=>s[0]===failedStage)?.[1]??'Design preparation'):'Current step: '+(outfitSteps.find(s=>s[0]===progressStage)?.[1]??'Invent design and prepare reference')}</p><ol>{outfitSteps.map(([key,label],i)=><li key={key} aria-current={key===progressStage?'step':undefined} className={i<outfitStepIndex(progressStage)?'complete':key===progressStage?'active':''}>{label}{i<outfitStepIndex(progressStage)?' ✓':''}</li>)}</ol>{failedStage&&<p className="hint-soft">If a usable generated image was retained, use Recover unfinished outfits below to resume fitting without generating again.</p>}</section>}{error&&<p role="alert" className="msg-error">{error}</p>}''',1)
s=s.replace('<div className="generated-design-grid">{designs.filter(d=>(d.name+\' \'+d.prompt).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort===\'name\'?a.name.localeCompare(b.name):sort===\'oldest\'?a.createdAt-b.createdAt:b.createdAt-a.createdAt).map(design=>', '''<label>Review status<select value={reviewFilter} onChange={e=>setReviewFilter(e.target.value)}><option value="all">All pending</option><option value="needs">Needs edits</option><option value="unmarked">Unmarked</option></select></label><div className="review-batch builder-actions"><button className="btn" disabled={running||!!acting} onClick={()=>setSelected(visible.map(d=>d.id))}>Select visible</button><button className="btn" disabled={running||!!acting} onClick={()=>setSelected([])}>Clear selection</button><span>{selected.length} selected</span><button className="btn" disabled={!selected.length||running||!!acting} onClick={()=>setConfirmBatch('approve')}>Save selected to Wardrobe</button><button className="btn" disabled={!selected.length||running||!!acting} onClick={()=>setConfirmBatch('dismiss')}>Dismiss selected</button></div>{confirmBatch&&<div className="review-batch-confirm" role="group" aria-label="Confirm batch review"><p>{confirmBatch==='approve'?'Save':'Dismiss'} {selected.length} selected designs?{confirmBatch==='approve'&&selected.some(id=>designs.find(d=>d.id===id)?.needsEdits)?' Selection includes designs marked Needs edits.':''}</p><button className="btn primary" onClick={()=>void batch(confirmBatch)}>Confirm {confirmBatch==='approve'?'save':'dismiss'}</button><button className="btn" onClick={()=>setConfirmBatch(undefined)}>Cancel</button></div>}<div className="generated-design-grid">{visible.map(design=>''',1)
s=s.replace('disabled={running||!!acting} onRename={reload}', "selected={selected.includes(design.id)} onSelect={()=>{setConfirmBatch(undefined);setSelected(ids=>ids.includes(design.id)?ids.filter(id=>id!==design.id):[...ids,design.id]);}} disabled={running||!!acting} onRename={reload}",1)
p.write_text(s,encoding='utf-8')
